// .NET 10 file-based program: scores DotCharter's AUTOMATIC chord fingering and FHP generation
// against hand-finished charts, and (optionally) against a hand-written answer key for Guitar Pro tabs.
//
//   charts mode (default): every RS-XML in --corpus is a finished chart. Its notes stay as they are;
//     its anchors and chord fingerings are stripped and regenerated by the production code, then
//     compared with what the charter shipped.
//   gold mode (--tabs <dir> --gold <tsv>): every GP tab is imported through the real GpImporter
//     (which generates anchors and fingerings), and the result is compared with a hand-written key.
//
// Usage and the measured baseline: tools/chart-eval/README.md.
#:project ../../DotCharter.Services/DotCharter.Services.csproj
#:property PublishAot=false
#:property Nullable=enable

using System.Diagnostics;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using DotCharter.Core.Domain.Events;
using DotCharter.Core.Domain.Guitar;
using DotCharter.Core.Domain.Primitives;
using DotCharter.Core.Domain.Project;
using DotCharter.Core.Utilities;
using DotCharter.Services.Editing.Fingering;
using DotCharter.Services.Editing.Fixing;
using DotCharter.Services.Editing.FretAnchors;
using DotCharter.Services.Parsing.GuitarPro;
using DotCharter.Services.Parsing.Xml;

// Stay out of the way of whoever is using this machine: upper half of the cores, idle priority.
try
{
    using var self = Process.GetCurrentProcess();
    self.PriorityClass = ProcessPriorityClass.Idle;
    if (Environment.ProcessorCount >= 16) self.ProcessorAffinity = (IntPtr)0xFF00;
}
catch (Exception) { /* best effort */ }

var opt = Options.Parse(args);
CultureInfo.DefaultThreadCurrentCulture = CultureInfo.InvariantCulture;
CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;

if (opt.Gold != null && opt.Tabs != null)
{
    GoldMode.Run(opt);
    return;
}

if (opt.Corpus == null)
{
    Console.Error.WriteLine("usage: dotnet run tools/chart-eval/ChartEval.cs -- --corpus <corpus.json> [--kind guitar|bass|all] [--split train|holdout|all] [--fhp-fingers auto|reference] [--free-fingering suggested|none] [--song <substr>] [--json <out.json>] [--baseline <old.json>] [--detail <out.tsv>] [--octaves <out.tsv>] [--sounds <out.tsv>] [--fixture <out.json>] [--style prefix|halves|loto|oracle|none]");
    Console.Error.WriteLine("       dotnet run tools/chart-eval/ChartEval.cs -- --corpus <corpus.json> --learn <LearnedChordFingeringData.cs>");
    Console.Error.WriteLine("       dotnet run tools/chart-eval/ChartEval.cs -- --tabs <dir> --gold <gold.tsv> [--detail <out.tsv>]");
    Environment.Exit(2);
}

if (opt.Learn != null)
{
    LearnMode.Run(opt);
    return;
}

ChartsMode.Run(opt);

internal sealed record Options(string? Corpus, string Kind, string Split, bool ReferenceFingers, string? Song,
    string? Json, string? Baseline, string? Detail, string? Tabs, string? Gold, bool FreeFingering, string? Octaves, string? Sounds,
    string? Learn, string? Fixture, string Style)
{
    public static Options Parse(string[] a)
    {
        string? Get(string k) { var i = Array.IndexOf(a, k); return i >= 0 && i + 1 < a.Length ? a[i + 1] : null; }
        return new Options(Get("--corpus"), Get("--kind") ?? "all", Get("--split") ?? "all",
            (Get("--fhp-fingers") ?? "auto") == "reference", Get("--song"), Get("--json"), Get("--baseline"),
            Get("--detail"), Get("--tabs"), Get("--gold"), (Get("--free-fingering") ?? "suggested") != "none", Get("--octaves"), Get("--sounds"),
            Get("--learn"), Get("--fixture"), Get("--style") ?? "prefix");
    }
}

/// <summary>Counters for one arrangement or a total. Every rate is a/b over the same population.</summary>
internal sealed class Score
{
    public int FhpSounds, FhpSame, AnchorsRef, AnchorsGen, ChangesRef, ChangesGen;
    public int Chords, ChordsExact, Strings, StringsSame, Templates, TemplatesExact;
    public int FollowChords, FollowExact, Refingered;
    // Bass octave-figure STARTS (#501): a fretted single note followed within the next two notes by the same string+2 /
    // fret+2, whose previous note was neither that root nor its octave. Agreement = the anchor governing the root sits
    // ON the root fret.
    public int OctaveStarts, OctaveRefOnRoot, OctaveGenOnRoot;
    public Dictionary<string, int[]> ByClass { get; } = [];

    public void Add(Score o)
    {
        FhpSounds += o.FhpSounds; FhpSame += o.FhpSame; AnchorsRef += o.AnchorsRef; AnchorsGen += o.AnchorsGen;
        ChangesRef += o.ChangesRef; ChangesGen += o.ChangesGen; Chords += o.Chords; ChordsExact += o.ChordsExact;
        Strings += o.Strings; StringsSame += o.StringsSame; Templates += o.Templates; TemplatesExact += o.TemplatesExact;
        FollowChords += o.FollowChords; FollowExact += o.FollowExact; Refingered += o.Refingered;
        OctaveStarts += o.OctaveStarts; OctaveRefOnRoot += o.OctaveRefOnRoot; OctaveGenOnRoot += o.OctaveGenOnRoot;
        foreach (var (k, v) in o.ByClass)
        {
            if (!ByClass.TryGetValue(k, out var t)) ByClass[k] = t = new int[2];
            t[0] += v[0]; t[1] += v[1];
        }
    }

    public static string Pct(int a, int b) => b == 0 ? "   -  " : $"{100.0 * a / b,5:0.0}%";

    public string Line() =>
        $"FHP same fret {Pct(FhpSame, FhpSounds)} of {FhpSounds,6} | anchor changes gen {ChangesGen,5} ref {ChangesRef,5} | " +
        $"chord fingering exact {Pct(ChordsExact, Chords)} of {Chords,5} (strings {Pct(StringsSame, Strings)}) | shapes exact {Pct(TemplatesExact, Templates)} of {Templates,4}" +
        $" | after FHP {Pct(FollowExact, FollowChords)} ({Refingered} re-fingered)";

    public Dictionary<string, object> ToJson() => new()
    {
        ["fhpSounds"] = FhpSounds, ["fhpSame"] = FhpSame, ["anchorsRef"] = AnchorsRef, ["anchorsGen"] = AnchorsGen,
        ["changesRef"] = ChangesRef, ["changesGen"] = ChangesGen, ["chords"] = Chords, ["chordsExact"] = ChordsExact,
        ["strings"] = Strings, ["stringsSame"] = StringsSame, ["templates"] = Templates, ["templatesExact"] = TemplatesExact,
        ["followChords"] = FollowChords, ["followExact"] = FollowExact, ["refingered"] = Refingered,
        ["octaveStarts"] = OctaveStarts, ["octaveRefOnRoot"] = OctaveRefOnRoot, ["octaveGenOnRoot"] = OctaveGenOnRoot,
    };

    public string OctaveLine() =>
        $"octave starts {OctaveStarts,5} | FHP on the root: reference {Pct(OctaveRefOnRoot, OctaveStarts)} generated {Pct(OctaveGenOnRoot, OctaveStarts)}";
}

internal static class ChartsMode
{
    public static void Run(Options opt)
    {
        var corpus = JsonDocument.Parse(File.ReadAllText(opt.Corpus!)).RootElement;
        var total = new Dictionary<string, Score> { ["guitar"] = new(), ["bass"] = new() };
        // --split all also reports each split on its own (one run instead of two).
        var bySplit = new SortedDictionary<string, Score>(StringComparer.Ordinal);
        var perArr = new Dictionary<string, Dictionary<string, object>>();
        var detail = opt.Detail != null ? new StreamWriter(opt.Detail) : null;
        detail?.WriteLine("song\tarrangement\tkind\tms\twhat\tnotes\tref\tgen");
        var octaves = opt.Octaves != null ? new StreamWriter(opt.Octaves) : null;
        octaves?.WriteLine(OctaveFigures.Header);
        var sounds = opt.Sounds != null ? new StreamWriter(opt.Sounds) : null;
        var fixture = opt.Fixture != null ? new FixtureWriter() : null;
        sounds?.WriteLine(SoundDump.Header);
        var seen = new HashSet<string>();
        var skipped = new List<string>();

        foreach (var song in corpus.EnumerateArray())
        {
            var name = song.GetProperty("song").GetString()!;
            if (opt.Song != null && !name.Contains(opt.Song, StringComparison.OrdinalIgnoreCase)) continue;
            var holdout = IsHoldout(name);
            if (opt.Split == "train" && holdout || opt.Split == "holdout" && !holdout) continue;

            foreach (var a in song.GetProperty("arrangements").EnumerateArray())
            {
                var kind = a.GetProperty("kind").GetString()!;
                if (opt.Kind != "all" && kind != opt.Kind) continue;
                var path = a.GetProperty("xml").GetString()!;
                ChartProject project;
                try { project = new XmlChartSerializer().Load(path); }
                catch (Exception ex) { skipped.Add($"{name}: {Path.GetFileName(path)} unreadable ({ex.GetType().Name})"); continue; }
                var arr = project.Arrangements.FirstOrDefault();
                if (arr == null || arr.Levels.Count == 0) continue;
                if (arr.Levels.Count > 1)
                {
                    // A DD chart's hardest level only holds the phrases that reach it; scoring it would
                    // score a fragment. Every finished chart in the owner's corpus is single-level.
                    skipped.Add($"{name}: {Path.GetFileName(path)} has {arr.Levels.Count} levels (DD) - skipped");
                    continue;
                }
                var level = arr.Levels[0];
                // The same arrangement is often exported twice (PART REAL_GUITAR + Lead_RS2); score it once.
                var sig = Signature(level);
                if (!seen.Add(name + "|" + sig)) continue;

                var s = ScoreArrangement(name, Path.GetFileName(path), kind, project, arr, level, opt.ReferenceFingers, opt.FreeFingering, detail, octaves, holdout, sounds, opt.Style);
                fixture?.Collect(name + "|" + Path.GetFileName(path), kind, arr, level);
                total[kind].Add(s);
                var splitKey = $"{(holdout ? "holdout" : "train")} {kind}";
                if (!bySplit.TryGetValue(splitKey, out var splitScore)) bySplit[splitKey] = splitScore = new Score();
                splitScore.Add(s);
                perArr[$"{name} | {Path.GetFileName(path)}"] = s.ToJson();
                Console.WriteLine($"{(holdout ? "H" : " ")} {Trunc(name, 40),-40} {Trunc(Path.GetFileNameWithoutExtension(path), 26),-26} {kind,-6} {s.Line()}");
            }
        }
        detail?.Dispose();
        octaves?.Dispose();
        sounds?.Dispose();
        fixture?.Write(opt.Fixture!);

        Console.WriteLine();
        var all = new Score();
        foreach (var (k, s) in total)
        {
            all.Add(s);
            Console.WriteLine($"TOTAL {k,-6} {s.Line()}");
        }
        Console.WriteLine($"TOTAL all    {all.Line()}");
        if (opt.Split == "all")
        {
            foreach (var (k, s) in bySplit)
                Console.WriteLine($"SPLIT {k,-14} {s.Line()} | FHP {100.0 * s.FhpSame / Math.Max(1, s.FhpSounds):0.00}% fingering {100.0 * s.FollowExact / Math.Max(1, s.FollowChords):0.00}%");
        }
        foreach (var (k, s) in total)
        {
            if (s.OctaveStarts > 0) Console.WriteLine($"TOTAL {k,-6} {s.OctaveLine()}");
        }
        Console.WriteLine();
        Console.WriteLine("Fingering exact by shape class (fretted strings, barre in the reference):");
        foreach (var (k, v) in all.ByClass.OrderByDescending(kv => kv.Value[1]))
            Console.WriteLine($"  {k,-14} {Score.Pct(v[0], v[1])} of {v[1]}");
        foreach (var s in skipped) Console.WriteLine("skipped: " + s);

        var json = new Dictionary<string, object>
        {
            ["split"] = opt.Split, ["kind"] = opt.Kind, ["style"] = opt.Style, ["fhpFingers"] = opt.ReferenceFingers ? "reference" : "auto", ["freeFingering"] = opt.FreeFingering ? "suggested" : "none",
            ["guitar"] = total["guitar"].ToJson(), ["bass"] = total["bass"].ToJson(), ["all"] = all.ToJson(), ["arrangements"] = perArr,
        };
        if (opt.Json != null) File.WriteAllText(opt.Json, JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true }));
        if (opt.Baseline != null) PrintDelta(opt.Baseline, json);
    }

    private static Score ScoreArrangement(string song, string file, string kind, ChartProject project, Arrangement arr,
        ChartLevel level, bool referenceFingers, bool freeFingering, StreamWriter? detail, StreamWriter? octaves, bool holdout,
        StreamWriter? soundDump, string style)
    {
        var s = new Score();
        var beats = project.Beats;
        var strings = arr.Tuning.Length > 0 ? arr.Tuning.Length : arr.StringCount;
        var templateById = arr.ChordTemplates.Where(t => t.Id >= 0).GroupBy(t => t.Id).ToDictionary(g => g.Key, g => g.First());

        // ---- chord fingering: the suggester on frets only (+ the arrangement's style, #511) vs the charter's fingers
        var hints = StyleHints.For(style, arr, level);
        var suggested = new Dictionary<int, ChordTemplate>();
        foreach (var t in arr.ChordTemplates)
        {
            var bare = new ChordTemplate { Id = t.Id, Name = t.Name, Arpeggio = t.Arpeggio, ForceArpeggioInRs = t.ForceArpeggioInRs };
            foreach (var (k, v) in t.Frets) bare.Frets[k] = v;
            ChordTemplateFingerSetter.SetSuggestedFingers(bare, strings, hints.GetValueOrDefault(t.Id));
            suggested[t.Id] = bare;
        }
        var scoredTemplates = new HashSet<int>();
        foreach (var chord in level.Chords)
        {
            if (!templateById.TryGetValue(chord.TemplateId, out var refT)) continue;
            var fretted = refT.Frets.Where(kv => kv.Value > 0).Select(kv => kv.Key).ToList();
            if (fretted.Count == 0 || fretted.Any(st => !refT.Fingers.TryGetValue(st, out var f) || f < 0)) continue;
            var gen = suggested[refT.Id];
            var same = fretted.Count(st => gen.Fingers.TryGetValue(st, out var g) && g == refT.Fingers[st]);
            s.Chords++; s.Strings += fretted.Count; s.StringsSame += same;
            var exact = same == fretted.Count;
            if (exact) s.ChordsExact++;
            var cls = $"{Math.Min(fretted.Count, 5)}str{(refT.Fingers.Values.Where(f => f > 0).GroupBy(f => f).Any(g => g.Count() > 1) ? "+barre" : "")}";
            if (!s.ByClass.TryGetValue(cls, out var c)) s.ByClass[cls] = c = new int[2];
            c[1]++; if (exact) c[0]++;
            if (scoredTemplates.Add(refT.Id))
            {
                s.Templates++;
                if (exact) s.TemplatesExact++;
                detail?.WriteLine($"{song}\t{file}\t{kind}\t\tfingering\t{Shape(refT, strings)}\t{Fingers(refT, strings)}\t{Fingers(gen, strings)}");
            }
        }

        // ---- FHP: regenerate on a copy of the level with no anchors
        var probe = new ChartLevel { DifficultyIndex = level.DifficultyIndex };
        foreach (var n in level.Notes) probe.Notes.Add(n);
        foreach (var c in level.Chords) probe.Chords.Add(c);
        foreach (var h in level.HandShapes) probe.HandShapes.Add(h);
        // Fingerings feed the anchor walk (a chord's index-finger fret). "auto" hands it the SUGGESTED
        // fingers, as a fresh chart would have; "reference" hands it the charter's, isolating the walk.
        var templates = referenceFingers ? arr.ChordTemplates.ToList() : arr.ChordTemplates.Select(t => suggested[t.Id]).ToList();
        // The production pipeline (#494): a chord whose fingering is the context-free suggestion is FREE, so the walk
        // may keep the hand where it is and ChordFingeringFollower re-fingers the chord to match. --free-fingering none
        // treats every fingering as authored (the pre-#494 walk).
        var evalArr = new Arrangement { Capo = arr.Capo, StringCount = arr.StringCount, Tuning = arr.Tuning };
        foreach (var t in templates) evalArr.ChordTemplates.Add(t);
        // Free = the suggestion under the SAME hint the template was suggested with.
        var isFree = freeFingering ? ChordFingeringFollower.FreeGripResolver(evalArr, null, t => hints.GetValueOrDefault(t.Id)) : null;
        var service = new FretAnchorGenerationService();
        // --sounds: which walk rule emitted each generated anchor (the internal measurement side-channel).
        var traceProp = soundDump == null ? null : typeof(FretAnchorGenerationService).GetProperty("RuleTrace",
            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
        var trace = traceProp == null ? null : (System.Collections.IDictionary)Activator.CreateInstance(traceProp.PropertyType)!;
        traceProp?.SetValue(service, trace);
        var generated = service
            .GenerateAnchors(probe, chordTemplates: templates, capo: arr.Capo, bassArrangement: kind == "bass",
                freeGrip: isFree, tuning: arr)
            .OrderBy(x => x.Position).ToList();
        var rules = new Dictionary<FractionalPosition, string>();
        if (trace != null)
        {
            foreach (System.Collections.DictionaryEntry e in trace) rules[(FractionalPosition)e.Key] = e.Value!.ToString()!;
        }

        // ---- chord fingering AFTER the FHP pass: the follower's variant where it re-fingered, else the walk's input
        var follow = isFree == null ? FingeringFollowPlan.Empty
            : ChordFingeringFollower.Plan(evalArr, probe, generated, isFree, new FingeringGenerationService());
        var finalId = new Dictionary<Chord, int>(ReferenceEqualityComparer.Instance);
        foreach (var (chord, _, newId) in follow.Chords) finalId[chord] = newId;
        var finalById = templates.Concat(follow.MintedTemplates).GroupBy(t => t.Id).ToDictionary(g => g.Key, g => g.First());
        s.Refingered = follow.Chords.Count;
        foreach (var chord in level.Chords)
        {
            if (!templateById.TryGetValue(chord.TemplateId, out var refT)) continue;
            var fretted = refT.Frets.Where(kv => kv.Value > 0).Select(kv => kv.Key).ToList();
            if (fretted.Count == 0 || fretted.Any(st => !refT.Fingers.TryGetValue(st, out var f) || f < 0)) continue;
            var id = finalId.TryGetValue(chord, out var nid) ? nid : chord.TemplateId;
            if (!finalById.TryGetValue(id, out var fin)) continue;
            s.FollowChords++;
            if (fretted.All(st => fin.Fingers.TryGetValue(st, out var g) && g == refT.Fingers[st])) s.FollowExact++;
        }
        var reference = level.Anchors.OrderBy(x => x.Position).ToList();
        s.AnchorsRef = reference.Count; s.AnchorsGen = generated.Count;
        if (reference.Count == 0) return s;
        if (kind == "bass") OctaveFigures.Score(s, song, file, holdout, arr, level, beats, reference, generated, octaves);
        if (soundDump != null)
            SoundDump.Write(soundDump, song, file, kind, holdout, arr, level, beats, reference, generated, templateById, suggested, finalById, finalId, strings, rules);

        var sounds = level.Notes.Where(n => n.Fret > arr.Capo).Select(n => (n.Position, Text: $"{n.StringIndex}:{n.Fret}"))
            .Concat(level.Chords.Where(c => c.ChordNotes.Any(n => n.Fret > arr.Capo))
                .Select(c => (c.Position, Text: string.Join(",", c.ChordNotes.Select(n => $"{n.StringIndex}:{n.Fret}")))))
            .OrderBy(x => x.Position).ToList();
        int? prevRef = null, prevGen = null;
        foreach (var (pos, text) in sounds)
        {
            var r = Governing(reference, pos);
            var g = Governing(generated, pos);
            if (r == null) continue;
            s.FhpSounds++;
            if (g == r) s.FhpSame++;
            else detail?.WriteLine($"{song}\t{file}\t{kind}\t{pos.GetPositionMs(beats):0}\tfhp\t{text}\t{r}\t{g}");
            if (prevRef != null && r != prevRef) s.ChangesRef++;
            if (prevGen != null && g != prevGen) s.ChangesGen++;
            prevRef = r; prevGen = g;
        }
        return s;
    }

    public static int? Governing(List<FretAnchor> anchors, FractionalPosition pos)
    {
        int? fret = null;
        foreach (var a in anchors)
        {
            if (a.Position > pos) break;
            fret = a.Fret;
        }
        return fret;
    }

    public static string Signature(ChartLevel level)
    {
        var sb = new StringBuilder();
        sb.Append(level.Notes.Count).Append('/').Append(level.Chords.Count).Append('/');
        foreach (var n in level.Notes.OrderBy(n => n.Position).Take(40)) sb.Append(n.StringIndex).Append(n.Fret).Append(';');
        return Convert.ToHexString(SHA1.HashData(Encoding.UTF8.GetBytes(sb.ToString())));
    }

    /// <summary>One song in five is held out from tuning, chosen by a stable hash of its name.</summary>
    public static bool IsHoldout(string song) => SHA1.HashData(Encoding.UTF8.GetBytes(song.ToLowerInvariant()))[0] % 5 == 0;

    private static string Shape(ChordTemplate t, int n) => string.Join("", Enumerable.Range(0, n).Select(st => t.Frets.TryGetValue(st, out var f) ? (f < 10 ? f.ToString() : $"({f})") : "x"));
    private static string Fingers(ChordTemplate t, int n) => string.Join("", Enumerable.Range(0, n).Select(st => !t.Frets.ContainsKey(st) ? "x" : t.Fingers.TryGetValue(st, out var f) && f >= 0 ? (f == 0 ? "T" : f.ToString()) : "-"));
    private static string Trunc(string s, int n) => s.Length <= n ? s : s[..n];

    private static void PrintDelta(string baselinePath, Dictionary<string, object> now)
    {
        var old = JsonDocument.Parse(File.ReadAllText(baselinePath)).RootElement;
        Console.WriteLine();
        Console.WriteLine($"Delta vs {Path.GetFileName(baselinePath)}:");
        foreach (var k in new[] { "guitar", "bass", "all" })
        {
            var o = old.GetProperty(k);
            var n = (Dictionary<string, object>)now[k];
            double R(JsonElement e, string a, string b) => e.GetProperty(b).GetInt32() == 0 ? 0 : 100.0 * e.GetProperty(a).GetInt32() / e.GetProperty(b).GetInt32();
            double Rn(string a, string b) => (int)n[b] == 0 ? 0 : 100.0 * (int)n[a] / (int)n[b];
            Console.WriteLine($"  {k,-6} FHP same {R(o, "fhpSame", "fhpSounds"):0.0}% -> {Rn("fhpSame", "fhpSounds"):0.0}% | changes gen {o.GetProperty("changesGen").GetInt32()} -> {n["changesGen"]} (ref {n["changesRef"]}) | " +
                              $"fingering exact {R(o, "chordsExact", "chords"):0.0}% -> {Rn("chordsExact", "chords"):0.0}%");
            if (o.TryGetProperty("octaveStarts", out var starts) && starts.GetInt32() > 0 && (int)n["octaveStarts"] > 0)
                Console.WriteLine($"         octave starts with the FHP on the root {R(o, "octaveGenOnRoot", "octaveStarts"):0.0}% -> {Rn("octaveGenOnRoot", "octaveStarts"):0.0}%");
        }
    }
}

/// <summary>
///     <c>--style</c> (#511): the per-template hint the suggester gets from the arrangement's OWN power-chord and
///     two-fret-octave fingering (<see cref="ArrangementFingeringStyle" />). A fair test gives the generator only what a
///     real chart would have, so a template's hint is NEVER computed from its own reference fingering:
///     <list type="bullet">
///         <item><c>prefix</c> (default): the hint from the templates first played BEFORE this one, as charting the song
///         from the start would have left them (the in-app flow: a template minted by an edit sees the ones already
///         there, fingered as the charter left them).</item>
///         <item><c>halves</c>: the templates first played in the first half of the arrangement's chords give the hint for
///         those first played in the second half, and the other way round (a 2-fold split by time).</item>
///         <item><c>loto</c>: leave one template out — the hint from every OTHER template (the charter fingered the rest
///         of the song and adds one new shape).</item>
///         <item><c>oracle</c>: the arrangement's whole majority, its own answer included. A ceiling, never a result.</item>
///         <item><c>none</c>: no hint (the suggester alone, as before #511).</item>
///     </list>
/// </summary>
internal static class StyleHints
{
    public static Dictionary<int, PairFingering?> For(string style, Arrangement arr, ChartLevel level)
    {
        var hints = new Dictionary<int, PairFingering?>();
        if (style == "none") return hints;
        var templates = arr.ChordTemplates.Where(t => t.Id >= 0).GroupBy(t => t.Id).Select(g => g.First()).ToList();
        var chords = level.Chords.OrderBy(c => c.Position).ToList();
        var first = new Dictionary<int, int>();
        for (var i = 0; i < chords.Count; i++) first.TryAdd(chords[i].TemplateId, i);
        int FirstUse(ChordTemplate t) => first.TryGetValue(t.Id, out var i) ? i : int.MaxValue;
        var firstHalf = templates.Where(t => FirstUse(t) == int.MaxValue || FirstUse(t) < chords.Count / 2).Select(t => t.Id).ToHashSet();

        var whole = ArrangementFingeringStyle.From(arr, templates);
        ArrangementFingeringStyle? fromFirst = null, fromSecond = null;
        foreach (var t in templates)
        {
            if (TwoFretPairFingering.Classify(arr, t, out _, out _) == null) continue;
            var source = style switch
            {
                "oracle" => whole,
                "loto" => ArrangementFingeringStyle.From(arr, templates.Where(o => o.Id != t.Id)),
                "prefix" => ArrangementFingeringStyle.From(arr, templates.Where(o => FirstUse(o) < FirstUse(t))),
                "halves" when firstHalf.Contains(t.Id) =>
                    fromSecond ??= ArrangementFingeringStyle.From(arr, templates.Where(o => !firstHalf.Contains(o.Id))),
                "halves" => fromFirst ??= ArrangementFingeringStyle.From(arr, templates.Where(o => firstHalf.Contains(o.Id))),
                _ => throw new ArgumentException($"--style {style}: halves, loto, oracle or none"),
            };
            hints[t.Id] = source.HintFor(arr, t);
        }

        return hints;
    }
}

/// <summary>
///     <c>--fixture</c> (#502 / #488): the SMALL committed fixture behind the default gate's accuracy floors
///     (<c>DotCharter.Tests/Services/Editing/FretAnchors/ChartStyleFloorTests</c>). One window of
///     <see cref="Length" /> struck positions from each of <see cref="PerKind" /> arrangements per instrument, picked by
///     a stable hash. A window holds frets, techniques that move the hand (slides, hammer-ons, pull-offs, taps), chord
///     shapes with the charter's fingers, hand-shape spans and the charter's anchors — positions are ORDINALS
///     (no timing), and nothing names or dates the song.
/// </summary>
internal sealed class FixtureWriter
{
    private const int Length = 48;
    private const int PerKind = 24;
    private readonly List<(string Kind, string Hash, Dictionary<string, object> Window)> _candidates = [];

    public void Collect(string key, string kind, Arrangement arr, ChartLevel level)
    {
        var capo = arr.Capo;
        var positions = level.Notes.Where(n => n.Fret > capo).Select(n => n.Position)
            .Concat(level.Chords.Where(c => c.ChordNotes.Any(n => n.Fret > capo)).Select(c => c.Position))
            .Distinct().OrderBy(p => p).ToList();
        var anchors = level.Anchors.OrderBy(a => a.Position).ToList();
        if (positions.Count < Length * 2 || anchors.Count == 0) return;

        var hash = Convert.ToHexString(SHA1.HashData(Encoding.UTF8.GetBytes(key)));
        var start = (int)(Convert.ToUInt32(hash[..8], 16) % (uint)(positions.Count - Length));
        // Open on a sound the charter placed an anchor at, so the window's first hand position is its own.
        var anchorAt = anchors.Select(a => a.Position).ToHashSet();
        while (start < positions.Count - Length && !anchorAt.Contains(positions[start])) start++;
        if (start >= positions.Count - Length) return;
        var window = positions.GetRange(start, Length);

        // An ordinal for any position: the index of the first window sound at or after it, minus a half when it
        // falls between two (a slide landing or a hand-shape edge on an empty beat).
        double Ordinal(FractionalPosition p)
        {
            var j = 0;
            while (j < window.Count && window[j] < p) j++;
            return j < window.Count && window[j] == p ? j : j - 0.5;
        }

        var byId = arr.ChordTemplates.Where(t => t.Id >= 0).GroupBy(t => t.Id).ToDictionary(g => g.Key, g => g.First());
        var sounds = new List<Dictionary<string, object>>();
        foreach (var p in window)
        {
            var entry = new Dictionary<string, object>();
            var notes = level.Notes.Where(n => n.Position == p && n.Fret > capo).Select(n => Note(n, p, Ordinal)).ToList();
            if (notes.Count > 0) entry["n"] = string.Join(",", notes);
            var chord = level.Chords.FirstOrDefault(c => c.Position == p && c.ChordNotes.Any(n => n.Fret > capo));
            if (chord != null)
            {
                entry["c"] = string.Join(",", chord.ChordNotes.Select(n => Note(n, p, Ordinal)));
                if (byId.TryGetValue(chord.TemplateId, out var t))
                    entry["f"] = string.Join(",", chord.ChordNotes.Select(n => t.Fingers.TryGetValue(n.StringIndex, out var f) && n.Fret > 0 ? f : -1));
            }
            entry["a"] = ChartsMode.Governing(anchors, p)!;
            sounds.Add(entry);
        }

        var shapes = level.HandShapes.Where(h => h.EndPosition > window[0] && h.Position <= window[^1])
            .OrderBy(h => h.Position)
            .Select(h => new[] { Math.Max(0, Ordinal(h.Position)), Ordinal(h.EndPosition) }).ToList();
        _candidates.Add((kind, hash, new Dictionary<string, object>
        {
            ["kind"] = kind, ["strings"] = arr.Tuning.Length > 0 ? arr.Tuning.Length : arr.StringCount, ["capo"] = capo,
            ["tuning"] = TuningOffsetResolution.Resolve(arr), ["sounds"] = sounds, ["shapes"] = shapes,
        }));
    }

    public void Write(string path)
    {
        var windows = _candidates.GroupBy(c => c.Kind).OrderBy(g => g.Key, StringComparer.Ordinal)
            .SelectMany(g => g.OrderBy(c => c.Hash, StringComparer.Ordinal).Take(PerKind)).Select(c => c.Window).ToList();
        var doc = new Dictionary<string, object>
        {
            ["about"] = "tools/chart-eval --fixture (#502): windows of the owner's finished charts, frets + techniques + " +
                        "reference fingers + reference anchors only, ordinal positions. Regenerate, never hand-edit.",
            ["windows"] = windows,
        };
        File.WriteAllText(path, JsonSerializer.Serialize(doc) + "\n");
        Console.WriteLine($"fixture: {windows.Count} windows of {Length} struck positions -> {path}");
    }

    // s:f, then a pitched slide "s<to>@<ordinal of its landing>", an unpitched one "u<to>", a hammer-on/pull-off/tap.
    private static string Note(IGuitarSound n, FractionalPosition at, Func<FractionalPosition, double> ordinal)
    {
        var sb = new StringBuilder($"{n.StringIndex}:{n.Fret}");
        if (n.SlideTo is > 0)
        {
            if (n.UnpitchedSlide) sb.Append('u').Append(n.SlideTo);
            else sb.Append('s').Append(n.SlideTo).Append('@').Append(ordinal(at + n.Sustain).ToString(CultureInfo.InvariantCulture));
        }
        if (n.Hopo != HopoType.None) sb.Append(n.Hopo switch { HopoType.HammerOn => 'h', HopoType.PullOff => 'p', _ => 't' });
        return sb.ToString();
    }
}

/// <summary>
///     <c>--learn</c> (#502): the chord shapes whose fingering the charters settle differently from
///     <c>ChordTemplateFingerSetter</c>'s heuristic, written as the generated
///     <c>DotCharter.Core/Utilities/LearnedChordFingeringData.cs</c>. TRAIN split only, whatever <c>--split</c> says:
///     a table that saw the held-out songs makes the held-out number meaningless. A shape is listed when one
///     fingering is at least <see cref="MinShare" /> of its chords, chosen in at least <see cref="MinSongs" /> songs,
///     and not what the heuristic already gives every one of them. A 5-fold song-grouped cross-validation on train
///     chose the thresholds: a shape from ONE song, or a share below 75%, lost accuracy on the songs left out; two
///     songs and three scored within 0.15 pp (+0.5 / +0.3 pp), and three is kept because a style two charts share
///     is still a habit (the Guitar Pro answer key disagrees with both two-song shapes it meets). Aggregated counts
///     only.
/// </summary>
internal static class LearnMode
{
    private const double MinShare = 0.75;
    private const int MinSongs = 3;

    public static void Run(Options opt)
    {
        var corpus = JsonDocument.Parse(File.ReadAllText(opt.Corpus!)).RootElement;
        var byKey = new SortedDictionary<string, Dictionary<string, (int Chords, HashSet<string> Songs)>>(StringComparer.Ordinal);
        // Per key, the heuristic's fingering of every chord (it depends on WHERE the shape sits for some shapes).
        var heuristic = new Dictionary<string, List<string>>(StringComparer.Ordinal);
        var seen = new HashSet<string>();
        int songs = 0, chords = 0;
        foreach (var song in corpus.EnumerateArray())
        {
            var name = song.GetProperty("song").GetString()!;
            if (ChartsMode.IsHoldout(name)) continue;
            songs++;
            foreach (var a in song.GetProperty("arrangements").EnumerateArray())
            {
                ChartProject project;
                try { project = new XmlChartSerializer().Load(a.GetProperty("xml").GetString()!); }
                catch (Exception) { continue; }
                var arr = project.Arrangements.FirstOrDefault();
                if (arr == null || arr.Levels.Count != 1) continue;
                if (!seen.Add(name + "|" + ChartsMode.Signature(arr.Levels[0]))) continue;
                var strings = arr.Tuning.Length > 0 ? arr.Tuning.Length : arr.StringCount;
                var byId = arr.ChordTemplates.Where(t => t.Id >= 0).GroupBy(t => t.Id).ToDictionary(g => g.Key, g => g.First());
                foreach (var chord in arr.Levels[0].Chords)
                {
                    if (!byId.TryGetValue(chord.TemplateId, out var t)) continue;
                    var fretted = t.Frets.Where(kv => kv.Value > 0).Select(kv => kv.Key).ToList();
                    if (fretted.Count == 0 || fretted.Any(st => !t.Fingers.TryGetValue(st, out var f) || f is < 0 or > 4)) continue;
                    var key = LearnedChordFingerings.KeyOf(t, strings)!;
                    var width = int.Parse(key[..key.IndexOf('|')], CultureInfo.InvariantCulture);
                    var fingers = Vector(t, width);
                    var bare = new ChordTemplate();
                    foreach (var (k, v) in t.Frets) bare.Frets[k] = v;
                    ChordTemplateFingerSetter.SetHeuristicFingers(bare, strings);
                    if (!heuristic.TryGetValue(key, out var h)) heuristic[key] = h = [];
                    h.Add(Vector(bare, width));
                    if (!byKey.TryGetValue(key, out var choices)) byKey[key] = choices = [];
                    var c = choices.TryGetValue(fingers, out var got) ? got : (Chords: 0, Songs: new HashSet<string>());
                    c.Songs.Add(name);
                    choices[fingers] = (c.Chords + 1, c.Songs);
                    chords++;
                }
            }
        }

        var rows = new List<string>();
        foreach (var (key, choices) in byKey)
        {
            var total = choices.Values.Sum(c => c.Chords);
            var best = choices.OrderByDescending(kv => kv.Value.Chords).ThenBy(kv => kv.Key, StringComparer.Ordinal).First();
            var (fingers, top) = (best.Key, best.Value);
            if (top.Chords < MinShare * total || top.Songs.Count < MinSongs || heuristic[key].All(h => h == fingers)) continue;
            rows.Add($"        new(\"{key}\", [{fingers}], {top.Chords}, {total}, {top.Songs.Count}),");
            Console.WriteLine($"{key,-24} heuristic [{heuristic[key].GroupBy(h => h).OrderByDescending(g => g.Count()).First().Key}] -> learned [{fingers}]  {top.Chords} of {total} chords, {top.Songs.Count} songs");
        }

        var sb = new StringBuilder();
        sb.Append("// <auto-generated>\n");
        sb.Append("//     Written by tools/chart-eval --learn (#502) from the TRAIN split of the owner's finished charts\n");
        sb.Append($"//     ({songs} songs, {chords} fingered chords). A shape is listed when one fingering is at least\n");
        sb.Append($"//     {MinShare * 100:0}% of its chords, chosen in at least {MinSongs} songs, and not ChordTemplateFingerSetter's\n");
        sb.Append("//     heuristic. Aggregated counts only. Regenerate it; never edit it by hand.\n");
        sb.Append("// </auto-generated>\n\n");
        sb.Append("namespace DotCharter.Core.Utilities;\n\n");
        sb.Append("/// <summary>The learned shapes behind <see cref=\"LearnedChordFingerings\" />: key, fingers, chords, of chords, songs.</summary>\n");
        sb.Append("internal static class LearnedChordFingeringData\n{\n");
        sb.Append("    internal static readonly LearnedChordFingering[] Shapes =\n    [\n");
        foreach (var r in rows) sb.Append(r).Append('\n');
        sb.Append("    ];\n}\n");
        File.WriteAllText(opt.Learn!, sb.ToString());
        Console.WriteLine($"{rows.Count} shapes from {songs} train songs, {chords} chords -> {opt.Learn}");
    }

    // One finger per string from the lowest, -1 where none (open, unused or unfingered).
    private static string Vector(ChordTemplate t, int width) => string.Join(", ", Enumerable.Range(0, width)
        .Select(s => t.Frets.TryGetValue(s, out var fret) && fret > 0 && t.Fingers.TryGetValue(s, out var f) && f >= 0 ? f : -1));
}

/// <summary>
///     <c>--sounds</c>: every fretted sound of every scored arrangement, one row each, with the reference and the
///     generated anchor governing it and (for a chord) the charter's, the suggested and the final fingering. The raw
///     material for measuring a lever before building it (#502). Owner-local output: it holds song content.
/// </summary>
internal static class SoundDump
{
    public const string Header =
        "song	arrangement	kind	split	capo	ord	ms	sustainMs	notes	chord	refFret	refWidth	refHere	genFret	genHere	shape	refFingers	suggFingers	finalFingers	handShape	genRule";

    public static void Write(StreamWriter w, string song, string file, string kind, bool holdout, Arrangement arr, ChartLevel level,
        IList<BeatMarker> beats, List<FretAnchor> reference, List<FretAnchor> generated, Dictionary<int, ChordTemplate> templateById,
        Dictionary<int, ChordTemplate> suggested, Dictionary<int, ChordTemplate> finalById, Dictionary<Chord, int> finalId, int strings,
        Dictionary<FractionalPosition, string> rules)
    {
        var capo = arr.Capo;
        var refAt = reference.Select(a => a.Position).ToHashSet();
        var genAt = generated.Select(a => a.Position).ToHashSet();
        var shapes = level.HandShapes.OrderBy(h => h.Position).ToList();
        var rows = level.Notes.Where(n => n.Fret > capo).Select(n => (n.Position, Note: (GuitarNote?)n, Chord: (Chord?)null))
            .Concat(level.Chords.Where(c => c.ChordNotes.Any(n => n.Fret > capo)).Select(c => (c.Position, Note: (GuitarNote?)null, Chord: (Chord?)c)))
            .OrderBy(x => x.Position).ToList();
        var ord = 0;
        foreach (var (pos, note, chord) in rows)
        {
            List<IGuitarSound> notes = note != null ? [note] : [.. chord!.ChordNotes];
            var text = string.Join(",", notes.Select(Note));
            var sustain = notes.Max(n => (pos + n.Sustain).GetPositionMs(beats) - pos.GetPositionMs(beats));
            var r = reference.LastOrDefault(a => a.Position <= pos);
            var g = generated.LastOrDefault(a => a.Position <= pos);
            string shape = "", rf = "", sf = "", ff = "";
            if (chord != null && templateById.TryGetValue(chord.TemplateId, out var t))
            {
                shape = Fmt(t.Frets, strings, f => f < 10 ? f.ToString() : $"({f})");
                rf = Fmt(t.Fingers, strings, f => f < 0 ? "-" : f == 0 ? "T" : f.ToString(), t.Frets);
                if (suggested.TryGetValue(t.Id, out var st)) sf = Fmt(st.Fingers, strings, f => f < 0 ? "-" : f == 0 ? "T" : f.ToString(), t.Frets);
                var id = finalId.TryGetValue(chord, out var nid) ? nid : chord.TemplateId;
                if (finalById.TryGetValue(id, out var ft)) ff = Fmt(ft.Fingers, strings, f => f < 0 ? "-" : f == 0 ? "T" : f.ToString(), t.Frets);
            }
            var hs = shapes.LastOrDefault(h => h.Position <= pos && pos < h.EndPosition);
            w.WriteLine(string.Join("	", song, file, kind, holdout ? "holdout" : "train", capo, ord++, pos.GetPositionMs(beats).ToString("0"),
                sustain.ToString("0"), text, chord != null ? 1 : 0, r?.Fret, r?.Width, r != null && refAt.Contains(pos) ? 1 : 0, g?.Fret,
                g != null && genAt.Contains(pos) ? 1 : 0, shape, rf, sf, ff, hs == null ? "" : $"{hs.Position.GetPositionMs(beats):0}",
                g != null && rules.TryGetValue(g.Position, out var rule) ? rule : ""));
        }
    }

    private static string Note(IGuitarSound n)
    {
        var sb = new StringBuilder($"{n.StringIndex}:{n.Fret}");
        if (n.SlideTo is > 0) sb.Append(n.UnpitchedSlide ? "u" : "s").Append(n.SlideTo);
        if (n.Hopo != HopoType.None) sb.Append(n.Hopo switch { HopoType.HammerOn => "h", HopoType.PullOff => "p", _ => "t" });
        if (n.Harmonic != HarmonicType.None) sb.Append('H');
        if (n.Mute == MuteType.Full) sb.Append('x');
        if (n.Mute == MuteType.Palm) sb.Append('m');
        if (n.BendValues.Count > 0) sb.Append('b');
        if (n.LinkNext) sb.Append('l');
        return sb.ToString();
    }

    private static string Fmt(Dictionary<int, int> map, int n, Func<int, string> f, Dictionary<int, int>? frets = null) =>
        string.Join("", Enumerable.Range(0, n).Select(st => (frets ?? map).ContainsKey(st) ? map.TryGetValue(st, out var v) ? f(v) : "-" : "x"));
}

/// <summary>
///     Bass octave figures (#501): the root, then the same note an octave up (two strings higher, two frets higher)
///     within the next two single notes. The owner's charts put the FHP on the root AT the root at 98% of the starts.
///     <c>--octaves</c> dumps every start, and every octave-DOWN start (the figure entered from its high note), with
///     the features the rule's edge cases were decided on.
/// </summary>
internal static class OctaveFigures
{
    public const string Header =
        "song\tarrangement\tsplit\tms\tdir\tstring\tfret\tgap\tprev\tslideIn\tslideOut\tref\tgen\trefAtOctave\tgenAtOctave\trefPrev\tgenPrev\trefAnchorHere";

    public static void Score(Score s, string song, string file, bool holdout, Arrangement arr, ChartLevel level,
        IList<BeatMarker> beats, List<FretAnchor> reference, List<FretAnchor> generated, StreamWriter? dump)
    {
        var capo = arr.Capo;
        var notes = level.Notes.OrderBy(n => n.Position).ToList();
        for (var i = 0; i < notes.Count; i++)
        {
            var root = notes[i];
            if (root.Fret <= capo) continue;
            foreach (var dir in new[] { 1, -1 })
            {
                var gap = 0;
                for (var j = i + 1; j <= i + 2 && j < notes.Count; j++)
                {
                    if (IsOctave(arr, root, notes[j], dir)) { gap = j - i; break; }
                }
                if (gap == 0) continue;
                var prev = i > 0 ? notes[i - 1] : null;
                if (prev != null && (Same(prev, root) || IsOctave(arr, root, prev, dir))) continue;

                var r = ChartsMode.Governing(reference, root.Position);
                var g = ChartsMode.Governing(generated, root.Position);
                if (dir == 1)
                {
                    s.OctaveStarts++;
                    if (r == root.Fret) s.OctaveRefOnRoot++;
                    if (g == root.Fret) s.OctaveGenOnRoot++;
                }
                if (dump == null) continue;
                var octave = notes[i + gap];
                var slideIn = prev != null && prev.StringIndex == root.StringIndex && prev.SlideTo is > 0;
                var slideOut = root.SlideTo is > 0;
                var refPrev = prev == null ? null : ChartsMode.Governing(reference, prev.Position);
                var genPrev = prev == null ? null : ChartsMode.Governing(generated, prev.Position);
                var refHere = reference.Any(a => a.Position == root.Position);
                dump.WriteLine(string.Join("\t", song, file, holdout ? "holdout" : "train", root.Position.GetPositionMs(beats).ToString("0"),
                    dir == 1 ? "up" : "down", root.StringIndex, root.Fret, gap, prev == null ? "" : $"{prev.StringIndex}:{prev.Fret}",
                    slideIn ? 1 : 0, slideOut ? 1 : 0, r, g, ChartsMode.Governing(reference, octave.Position),
                    ChartsMode.Governing(generated, octave.Position), refPrev, genPrev, refHere ? 1 : 0));
            }
        }
    }

    private static bool Same(GuitarNote a, GuitarNote b) => a.StringIndex == b.StringIndex && a.Fret == b.Fret;

    // The shape, and the SOUND through the chart's tuning (#507 review: drop D's low string + 2 is a ninth).
    private static bool IsOctave(Arrangement arr, GuitarNote root, GuitarNote other, int dir) =>
        other.StringIndex == root.StringIndex + 2 * dir && other.Fret == root.Fret + 2 * dir &&
        SoundingPitch.MidiFor(arr, other.StringIndex, other.Fret) - SoundingPitch.MidiFor(arr, root.StringIndex, root.Fret) == 12 * dir;
}

/// <summary>
///     Scores the tab import (GpImporter, which generates anchors and fingers) against a hand-written key.
///     Gold TSV columns: file  track  ms  notes  anchorFret  fingers  [comment]
///       file   = GP file name without extension;  track = GP track name
///       ms     = the sound's position in ms on the tab's own tempo map (as GpBeatMapBuilder builds it,
///                initial bpm from the file, start offset 0), matched within 3 ms
///       notes  = "string:fret" pairs, string 0 = lowest, comma-separated, any order
///       anchorFret = the FHP fret that should govern this sound (empty = not judged)
///       fingers    = "string:finger" pairs for a chord, finger 0 = thumb, 1-4 (empty = not judged)
/// </summary>
internal static class GoldMode
{
    public static void Run(Options opt)
    {
        var gold = File.ReadAllLines(opt.Gold!).Where(l => l.Length > 0 && !l.StartsWith('#') && !l.StartsWith("file\t"))
            .Select(l => l.Split('\t')).Where(c => c.Length >= 6).ToList();
        var byFile = gold.GroupBy(c => c[0]);
        var detail = opt.Detail != null ? new StreamWriter(opt.Detail) : null;
        int fhpN = 0, fhpSame = 0, fingN = 0, fingSame = 0, unmatched = 0;
        foreach (var g in byFile)
        {
            var path = Directory.GetFiles(opt.Tabs!, "*.gp*").FirstOrDefault(p => Path.GetFileNameWithoutExtension(p) == g.Key);
            if (path == null) { Console.WriteLine($"no tab for {g.Key}"); continue; }
            var importer = new GpImporter();
            var tracks = importer.GetAvailableTracks(path);
            var result = importer.ImportTracksWithMetadata(path, tracks.Select(t => t.Id).ToList());
            var beats = GpBeatMapBuilder.Build(result.Metadata, GpBeatMapBuilder.InitialBpm(result.Metadata, 120), 0);
            int fN = 0, fS = 0, cN = 0, cS = 0;
            foreach (var row in g)
            {
                var arr = result.Arrangements.FirstOrDefault(a => a.Name == row[1]);
                var level = arr?.Levels.OrderByDescending(l => l.DifficultyIndex).FirstOrDefault();
                if (arr == null || level == null) { unmatched++; continue; }
                var ms = double.Parse(row[2], CultureInfo.InvariantCulture);
                var want = Norm(row[3]);
                FractionalPosition? pos = null; Chord? chord = null;
                foreach (var n in level.Notes)
                {
                    if (Math.Abs(n.Position.GetPositionMs(beats) - ms) <= 3 && Norm($"{n.StringIndex}:{n.Fret}") == want) { pos = n.Position; break; }
                }
                if (pos == null)
                {
                    chord = level.Chords.FirstOrDefault(c => Math.Abs(c.Position.GetPositionMs(beats) - ms) <= 3 &&
                        Norm(string.Join(",", c.ChordNotes.Select(n => $"{n.StringIndex}:{n.Fret}"))) == want);
                    pos = chord?.Position;
                }
                if (pos == null) { unmatched++; continue; }

                if (int.TryParse(row[4], out var wantAnchor))
                {
                    var anchor = level.Anchors.Where(a => a.Position <= pos.Value).OrderBy(a => a.Position).LastOrDefault();
                    fN++; if (anchor?.Fret == wantAnchor) fS++;
                    else detail?.WriteLine($"{g.Key}\t{row[1]}\t{row[2]}\tfhp\t{row[3]}\t{wantAnchor}\t{anchor?.Fret}");
                }
                if (chord != null && row[5].Length > 0)
                {
                    var t = arr.ChordTemplates.FirstOrDefault(x => x.Id == chord.TemplateId);
                    var wantF = row[5].Split(',').Select(p => p.Split(':')).ToDictionary(p => int.Parse(p[0]), p => int.Parse(p[1]));
                    cN++;
                    if (t != null && wantF.All(kv => t.Fingers.TryGetValue(kv.Key, out var f) && f == kv.Value)) cS++;
                    else detail?.WriteLine($"{g.Key}\t{row[1]}\t{row[2]}\tfingering\t{row[3]}\t{row[5]}\t{(t == null ? "" : string.Join(",", t.Fingers.Select(kv => $"{kv.Key}:{kv.Value}")))}");
                }
            }
            fhpN += fN; fhpSame += fS; fingN += cN; fingSame += cS;
            Console.WriteLine($"{Trunc(g.Key, 50),-50} FHP {Score.Pct(fS, fN)} of {fN,5} | chord fingering {Score.Pct(cS, cN)} of {cN,4}");
        }
        detail?.Dispose();
        Console.WriteLine($"TOTAL FHP {Score.Pct(fhpSame, fhpN)} of {fhpN} | chord fingering {Score.Pct(fingSame, fingN)} of {fingN} | unmatched gold rows {unmatched}");
    }

    private static string Norm(string notes) => string.Join(",", notes.Split(',', StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).OrderBy(x => x, StringComparer.Ordinal));
    private static string Trunc(string s, int n) => s.Length <= n ? s : s[..n];
}
